    async Task RefreshEventStatuses()=> await Exec("UPDATE ExternalEvents SET RegistrationStatus=CASE WHEN RegistrationDeadline IS NOT NULL AND RegistrationDeadline<CONVERT(date,GETDATE()) THEN 'Closed' ELSE 'Open' END,UpdatedAt=CASE WHEN RegistrationStatus<>CASE WHEN RegistrationDeadline IS NOT NULL AND RegistrationDeadline<CONVERT(date,GETDATE()) THEN 'Closed' ELSE 'Open' END THEN SYSUTCDATETIME() ELSE UpdatedAt END");
    public async Task<List<object>> PublicEvents() { await EnsureAsync(); await RefreshEventStatuses(); return await Query("SELECT EventId,EventName,HostingInstitution,EventPortal,RegistrationStatus,Category,Venue,EventFrom,EventTo,RegistrationDeadline,EventType,StudentMessage,MessageSharedAt,RegistrationMode,MinParticipants,MaxParticipants FROM ExternalEvents ORDER BY CreatedAt DESC", r => (object)new { eventId=r.GetInt32(0),eventName=r.GetString(1),hostingInstitution=r.GetString(2),eventPortal=r.IsDBNull(3)?"":r.GetString(3),registrationStatus=r.GetString(4),category=r.IsDBNull(5)?"":r.GetString(5),venue=r.IsDBNull(6)?"":r.GetString(6),eventFrom=r.IsDBNull(7)?(DateTime?)null:r.GetDateTime(7),eventTo=r.IsDBNull(8)?(DateTime?)null:r.GetDateTime(8),registrationDeadline=r.IsDBNull(9)?(DateTime?)null:r.GetDateTime(9),eventType=r.IsDBNull(10)?"":r.GetString(10),studentMessage=r.IsDBNull(11)?"":r.GetString(11),messageSharedAt=r.IsDBNull(12)?(DateTime?)null:r.GetDateTime(12),registrationMode=r.IsDBNull(13)?"Team":r.GetString(13),minParticipants=r.IsDBNull(14)?1:r.GetInt32(14),maxParticipants=r.IsDBNull(15)?10:r.GetInt32(15)}); }
    public async Task<List<object>> Mentors() { await EnsureAsync(); return await Query("SELECT MentorId,MentorName,Designation FROM EventMentors WHERE IsActive=1 ORDER BY MentorName", r => (object)new { mentorId=r.GetInt32(0),mentorName=r.GetString(1),designation=r.GetString(2)}); }
    public async Task<List<object>> WinningTeams(){await EnsureAsync();return await Query("SELECT WinningTeamId,SocialMediaUrl,PhotoName,UpdatedAt FROM EventWinningTeams ORDER BY CreatedAt DESC",r=>(object)new{winningTeamId=r.GetInt32(0),socialMediaUrl=r.GetString(1),photoName=r.GetString(2),updatedAt=r.GetDateTime(3)});}
    public async Task<object> SaveWinningTeam(int? id,string socialMediaUrl,IFormFile? photo){await EnsureAsync();if(!Uri.TryCreate(socialMediaUrl,UriKind.Absolute,out var uri)||!uri.Host.EndsWith("instagram.com",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("Enter a valid Instagram URL.");if(id is null&&photo is null)throw new ArgumentException("Upload a winning team photo.");byte[]? data=null;if(photo is not null){if(!new[]{"image/jpeg","image/png","image/webp"}.Contains(photo.ContentType)||photo.Length>8_000_000)throw new ArgumentException("Upload a JPG, PNG or WebP photo up to 8 MB.");await using var memory=new MemoryStream();await photo.CopyToAsync(memory);data=memory.ToArray();}if(id is null){await Exec("INSERT EventWinningTeams(SocialMediaUrl,PhotoName,PhotoContentType,PhotoData) VALUES(@u,@n,@c,@d)",new("@u",socialMediaUrl.Trim()),new("@n",Path.GetFileName(photo!.FileName)),new("@c",photo.ContentType),new SqlParameter("@d",SqlDbType.VarBinary,-1){Value=data!});}else if(photo is null)await Exec("UPDATE EventWinningTeams SET SocialMediaUrl=@u,UpdatedAt=SYSUTCDATETIME() WHERE WinningTeamId=@id",new("@u",socialMediaUrl.Trim()),new("@id",id));else await Exec("UPDATE EventWinningTeams SET SocialMediaUrl=@u,PhotoName=@n,PhotoContentType=@c,PhotoData=@d,UpdatedAt=SYSUTCDATETIME() WHERE WinningTeamId=@id",new("@u",socialMediaUrl.Trim()),new("@n",Path.GetFileName(photo.FileName)),new("@c",photo.ContentType),new SqlParameter("@d",SqlDbType.VarBinary,-1){Value=data!},new("@id",id));return new{message="Winning team saved."};}
    public Task<int> DeleteWinningTeam(int id)=>Exec("DELETE EventWinningTeams WHERE WinningTeamId=@id",new SqlParameter("@id",id));
    public async Task<(byte[] Data,string Name,string ContentType)?> WinningTeamPhoto(int id){await EnsureAsync();var rows=await Query("SELECT PhotoData,PhotoName,PhotoContentType FROM EventWinningTeams WHERE WinningTeamId=@id",r=>((byte[])r[0],r.GetString(1),r.GetString(2)),new SqlParameter("@id",id));return rows.Count==0?null:rows[0];}
    public async Task<List<object>> PublicTeams() { await EnsureAsync(); return await Query("SELECT t.TeamNumber,e.EventName,t.Category,t.Mentor,CASE WHEN t.PostEventStatus='Yet to update' THEN 'Registered' WHEN t.PostEventStatus='Participated and Won the Competition' THEN 'Won the Competition' ELSE t.PostEventStatus END PublicStatus,(SELECT Name,USN,Semester,Branch,Mobile,Email,IsLeader FROM EventTeamMembers m WHERE m.TeamId=t.TeamId ORDER BY IsLeader DESC,MemberId FOR JSON PATH) Members,COALESCE(em.Designation,'Assistant Professor') MentorDesignation FROM EventTeams t JOIN ExternalEvents e ON e.EventId=t.EventId LEFT JOIN EventMentors em ON em.MentorName=t.Mentor WHERE t.IsDeleted=0 AND t.TeamNumber IS NOT NULL AND t.ApprovalStatus='Approved' AND t.Status NOT IN ('Rejected','Pending Approval') ORDER BY t.TeamNumber", r => (object)new {teamNumber=r.GetString(0),eventName=r.GetString(1),category=r.GetString(2),mentor=r.IsDBNull(3)?"":r.GetString(3),status=r.GetString(4),members=System.Text.Json.JsonSerializer.Deserialize<object>(r.GetString(5)),mentorDesignation=r.GetString(6)}); }
    public async Task<object> PublicTeamSummary(){await EnsureAsync();var rows=await Query("SELECT COUNT(*),SUM(CASE WHEN PostEventStatus='Participated' OR PostEventStatus LIKE '%Won%' THEN 1 ELSE 0 END),SUM(CASE WHEN PostEventStatus='Not Participated' THEN 1 ELSE 0 END),SUM(CASE WHEN PostEventStatus LIKE '%Won%' THEN 1 ELSE 0 END) FROM EventTeams WHERE IsDeleted=0 AND TeamNumber IS NOT NULL AND ApprovalStatus<>'Not Approved' AND Status<>'Rejected'",r=>(object)new{registered=r.GetInt32(0),participated=r.IsDBNull(1)?0:r.GetInt32(1),notParticipated=r.IsDBNull(2)?0:r.GetInt32(2),won=r.IsDBNull(3)?0:r.GetInt32(3)});return rows[0];}
    public async Task<(string RegistrationReference,string TeamNumber,string Password)> Register(EventRegistrationRequest x)
    {
        await EnsureAsync(); if (!x.DeclarationAccepted || x.Members.Count==0) throw new ArgumentException("Accept the declaration and provide participant details.");
        await RefreshEventStatuses();
        var rules=await Query("SELECT RegistrationStatus,RegistrationMode,MinParticipants,MaxParticipants,EventType FROM ExternalEvents WHERE EventId=@id",r=>(Status:r.GetString(0),Mode:r.GetString(1),Min:r.GetInt32(2),Max:r.GetInt32(3),Type:r.IsDBNull(4)?"":r.GetString(4)),new SqlParameter("@id",x.EventId));
        if(rules.Count==0)throw new ArgumentException("The selected event could not be found.");
        var rule=rules[0];
        if(x.RegistrationMode is not ("Individual" or "Team"))throw new ArgumentException("Select Individual or Team registration.");
        if(x.RegistrationMode=="Individual"&&x.Members.Count!=1)throw new ArgumentException("Individual registration requires exactly one participant.");
        if(x.RegistrationMode=="Team"&&(x.Members.Count<rule.Min||x.Members.Count>rule.Max))throw new ArgumentException($"This event requires {rule.Min}-{rule.Max} team members.");
        if(x.Members.Count(m=>m.IsLeader)!=1)throw new ArgumentException(x.RegistrationMode=="Individual"?"Select the participant.":"Select exactly one team leader.");
        var submittedUsns=x.Members.Select(m=>m.Usn.Trim().ToUpperInvariant()).ToList();
        if(submittedUsns.Any(string.IsNullOrWhiteSpace)||submittedUsns.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=submittedUsns.Count)throw new ArgumentException("Every participant must have a unique, valid USN.");
        var sameEventTeams=await Query("SELECT TeamId FROM EventTeams WHERE EventId=@id AND IsDeleted=0",r=>r.GetInt32(0),new SqlParameter("@id",x.EventId));
        foreach(var existingTeamId in sameEventTeams){var existingUsns=await Query("SELECT UPPER(LTRIM(RTRIM(USN))) FROM EventTeamMembers WHERE TeamId=@id",r=>r.GetString(0),new SqlParameter("@id",existingTeamId));if(existingUsns.Count==submittedUsns.Count&&new HashSet<string>(existingUsns,StringComparer.OrdinalIgnoreCase).SetEquals(submittedUsns))throw new ArgumentException("This Student/Team is already registered for the selected event. Duplicate registration is not allowed.");}
        if(!string.IsNullOrWhiteSpace(x.Mentor)&&Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM EventMentors WHERE MentorName=@m AND IsActive=1",new SqlParameter("@m",x.Mentor.Trim()))??0)==0)throw new ArgumentException("Select a valid faculty mentor/guide.");
        var reference=$"EVR-{DateTime.UtcNow:yyMMdd}-{RandomNumberGenerator.GetInt32(1000,9999)}";
        await using var c=new SqlConnection(cs); await c.OpenAsync(); await using var tx=await c.BeginTransactionAsync();
        var cmd=new SqlCommand("INSERT EventTeams(RegistrationReference,EventId,RegistrationMode,Category,Mentor,DeclarationAccepted) OUTPUT INSERTED.TeamId VALUES(@r,@e,@mode,@c,@m,1)",c,(SqlTransaction)tx); cmd.Parameters.AddRange([new("@r",reference),new("@e",x.EventId),new("@mode",x.RegistrationMode),new("@c",rule.Type),new("@m",string.IsNullOrWhiteSpace(x.Mentor)?DBNull.Value:x.Mentor.Trim())]); var id=(int)(await cmd.ExecuteScalarAsync())!;
        var teamNumber=$"CSE-EVT-{DateTime.Now:yy}-{id:000}";
        var password=$"Atme@{RandomNumberGenerator.GetInt32(100000,999999)}";
        var credentialCipher=ProtectCredential(password);
        var credentials=new SqlCommand("UPDATE EventTeams SET TeamNumber=@n,PasswordHash=@p,CredentialCipher=@x,MustChangePassword=1,Status='Registered',ApprovalStatus='Pending',PostEventStatus='Yet to update' WHERE TeamId=@id",c,(SqlTransaction)tx);
        credentials.Parameters.AddRange([new("@n",teamNumber),new("@p",PasswordSecurity.Hash(password)),new("@x",credentialCipher),new("@id",id)]);await credentials.ExecuteNonQueryAsync();
        foreach(var m in x.Members){ var q=new SqlCommand("INSERT EventTeamMembers(TeamId,Name,USN,Semester,Branch,Mobile,Email,IsLeader) VALUES(@t,@n,@u,@s,@b,@p,@e,@l)",c,(SqlTransaction)tx); q.Parameters.AddRange([new("@t",id),new("@n",m.Name.Trim()),new("@u",m.Usn.Trim().ToUpperInvariant()),new("@s",m.Semester.Trim()),new("@b",m.Branch.Trim()),new("@p",m.Mobile.Trim()),new("@e",m.Email.Trim()),new("@l",m.IsLeader)]); await q.ExecuteNonQueryAsync(); }
        await tx.CommitAsync(); return (reference,teamNumber,password);
    }
    public async Task<EventLoginResponse?> Login(string type,EventLoginRequest x)
    {
        await EnsureAsync(); string sql=type=="Coordinator"?"SELECT CoordinatorId,DisplayName,PasswordHash,MustChangePassword FROM EventCoordinators WHERE Username=@u":type=="Mentor"?"SELECT MentorUserId,DisplayName,PasswordHash,MustChangePassword FROM EventMentorUsers WHERE Username=@u":"SELECT TeamId,COALESCE(TeamNumber,RegistrationReference),PasswordHash,MustChangePassword FROM EventTeams WHERE TeamNumber=@u AND IsDeleted=0";
        await using var c=new SqlConnection(cs); await c.OpenAsync(); await using var cmd=new SqlCommand(sql,c); cmd.Parameters.AddWithValue("@u",x.Username.Trim()); await using var r=await cmd.ExecuteReaderAsync(); if(!await r.ReadAsync()||r.IsDBNull(2)||!PasswordSecurity.Verify(x.Password,r.GetString(2))) return null; var id=r.GetInt32(0); var name=r.GetString(1); var must=r.GetBoolean(3); await r.CloseAsync();
        var token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32)); var exp=DateTime.UtcNow.AddHours(type is "Coordinator" or "Mentor"?8:4); await Exec("INSERT EventAuthSessions VALUES(@h,@t,@i,@e,SYSUTCDATETIME())",new("@h",Hash(token)),new("@t",type),new("@i",id),new("@e",exp)); return new(token,type,name,must,exp);
    }
