    static string Hash(string x)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(x)));
    byte[] CredentialKey()=>SHA256.HashData(Encoding.UTF8.GetBytes($"EventPortal.TeamCredentials.v2|{cs}"));
    string ProtectCredential(string value){var nonce=RandomNumberGenerator.GetBytes(12);var plain=Encoding.UTF8.GetBytes(value);var cipher=new byte[plain.Length];var tag=new byte[16];using var aes=new AesGcm(CredentialKey(),16);aes.Encrypt(nonce,plain,cipher,tag);var payload=new byte[nonce.Length+tag.Length+cipher.Length];Buffer.BlockCopy(nonce,0,payload,0,nonce.Length);Buffer.BlockCopy(tag,0,payload,nonce.Length,tag.Length);Buffer.BlockCopy(cipher,0,payload,nonce.Length+tag.Length,cipher.Length);return "v2:"+Convert.ToBase64String(payload);}
    string? TryUnprotectCredential(string value){try{if(value.StartsWith("v2:",StringComparison.Ordinal)){var payload=Convert.FromBase64String(value[3..]);if(payload.Length<29)return null;var nonce=payload[..12];var tag=payload[12..28];var cipher=payload[28..];var plain=new byte[cipher.Length];using var aes=new AesGcm(CredentialKey(),16);aes.Decrypt(nonce,cipher,tag,plain);return Encoding.UTF8.GetString(plain);}return credentialProtector.Unprotect(value);}catch{return null;}}
    string UnprotectCredential(string value)=>TryUnprotectCredential(value)??"Password unavailable - reset required";
    async Task EnsureMissingTeamCredentials(){var rows=await Query("SELECT TeamId,CredentialCipher FROM EventTeams WHERE TeamNumber IS NOT NULL AND IsDeleted=0",r=>(Id:r.GetInt32(0),Cipher:r.IsDBNull(1)?null:r.GetString(1)));foreach(var row in rows){var current=string.IsNullOrWhiteSpace(row.Cipher)?null:TryUnprotectCredential(row.Cipher);if(current is not null){if(!row.Cipher!.StartsWith("v2:",StringComparison.Ordinal))await Exec("UPDATE EventTeams SET CredentialCipher=@x WHERE TeamId=@id",new("@x",ProtectCredential(current)),new("@id",row.Id));continue;}var password=$"Atme@{RandomNumberGenerator.GetInt32(100000,999999)}";await Exec("UPDATE EventTeams SET PasswordHash=@p,CredentialCipher=@x,MustChangePassword=1,UpdatedAt=SYSUTCDATETIME() WHERE TeamId=@id",new("@p",PasswordSecurity.Hash(password)),new("@x",ProtectCredential(password)),new("@id",row.Id));}}
    async Task RemoveSafeDuplicateRegistrations(){var teams=await Query("SELECT t.TeamId,t.EventId,t.CreatedAt,CASE WHEN t.ApprovalStatus='Pending' AND t.PostEventStatus='Yet to update' AND NOT EXISTS(SELECT 1 FROM EventFiles f WHERE f.TeamId=t.TeamId) THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END FROM EventTeams t WHERE t.IsDeleted=0 ORDER BY t.CreatedAt,t.TeamId",r=>(Id:r.GetInt32(0),EventId:r.GetInt32(1),CreatedAt:r.GetDateTime(2),Deletable:r.GetBoolean(3)));var records=new List<(int Id,int EventId,DateTime CreatedAt,bool Deletable,string MemberKey)>();foreach(var team in teams){var usns=await Query("SELECT UPPER(LTRIM(RTRIM(USN))) FROM EventTeamMembers WHERE TeamId=@id ORDER BY UPPER(LTRIM(RTRIM(USN)))",r=>r.GetString(0),new SqlParameter("@id",team.Id));if(usns.Count>0)records.Add((team.Id,team.EventId,team.CreatedAt,team.Deletable,string.Join("|",usns)));}foreach(var group in records.GroupBy(x=>(x.EventId,x.MemberKey))){var ordered=group.OrderBy(x=>x.Deletable?1:0).ThenBy(x=>x.CreatedAt).ThenBy(x=>x.Id).ToList();foreach(var duplicate in ordered.Skip(1).Where(x=>x.Deletable))await Exec("DELETE EventAuthSessions WHERE PrincipalType='Team' AND PrincipalId=@id; DELETE EventTeams WHERE TeamId=@id",new SqlParameter("@id",duplicate.Id));}}
    async Task<int> Exec(string sql,params SqlParameter[] p){await using var c=new SqlConnection(cs);await c.OpenAsync();await using var q=new SqlCommand(sql,c);q.Parameters.AddRange(p);return await q.ExecuteNonQueryAsync();}
    async Task<object?> Scalar(string sql,params SqlParameter[] p){await using var c=new SqlConnection(cs);await c.OpenAsync();await using var q=new SqlCommand(sql,c);q.Parameters.AddRange(p);return await q.ExecuteScalarAsync();}
    async Task<List<T>> Query<T>(string sql,Func<SqlDataReader,T> map,params SqlParameter[] p){var x=new List<T>();await using var c=new SqlConnection(cs);await c.OpenAsync();await using var q=new SqlCommand(sql,c);q.Parameters.AddRange(p.Where(z=>z.ParameterName!="@t"||sql.Contains("@t")).ToArray());await using var r=await q.ExecuteReaderAsync();while(await r.ReadAsync())x.Add(map(r));return x;}
